#include "sdk_controllers_native.h"

/* Private, generated by the pinned unmodified SDL build. Never substitute a
 * project constant for the actual selected backend configuration. */
#include "SDL_build_config.h"
#include <SDL3/SDL_error.h>
#include <SDL3/SDL_init.h>
#include <SDL3/SDL_joystick.h>
#include <stdio.h>
#include <stdlib.h>

_Static_assert(sizeof(SDL_JoystickID) == sizeof(uint32_t), "SDL joystick ID width");

static mc_client_sdk_input_status native_failure(mc_client_sdk_input_error *e,
                                                 mc_client_sdk_input_status status,
                                                 const char *operation, int32_t pc) {
    if (e != NULL) {
        *e = (mc_client_sdk_input_error){0};
        e->status = status;
        e->operation = operation;
        e->site = (mc_client_sdk_input_site){"org/lwjgl/input/Controllers", "create", "()V", pc};
        e->native_policy = true;
    }
    return status;
}

static void remember(mc_client_sdk_controller_environment *env,
                     const mc_client_sdk_input_error *error) {
    if (env->failure.status == MC_CLIENT_SDK_INPUT_OK && error != NULL)
        env->failure = *error;
}

uint32_t mc_client_sdk_controller_native_backends(void) {
    uint32_t mask = 0;
#if defined(SDL_JOYSTICK_LINUX)
    mask |= MC_CLIENT_SDK_CONTROLLER_LINUX;
#endif
#if defined(SDL_JOYSTICK_RAWINPUT)
    mask |= MC_CLIENT_SDK_CONTROLLER_RAWINPUT;
#endif
#if defined(SDL_JOYSTICK_DINPUT)
    mask |= MC_CLIENT_SDK_CONTROLLER_DINPUT;
#endif
#if defined(SDL_JOYSTICK_XINPUT)
    mask |= MC_CLIENT_SDK_CONTROLLER_XINPUT;
#endif
#if defined(SDL_JOYSTICK_WGI)
    mask |= MC_CLIENT_SDK_CONTROLLER_WGI;
#endif
#if defined(SDL_JOYSTICK_GAMEINPUT)
    mask |= MC_CLIENT_SDK_CONTROLLER_GAMEINPUT;
#endif
#if defined(SDL_JOYSTICK_VIRTUAL)
    mask |= MC_CLIENT_SDK_CONTROLLER_VIRTUAL;
#endif
    return mask;
}

mc_client_sdk_input_status
mc_client_sdk_controller_environment_allocate(mc_client_sdk_controller_environment **out,
                                              mc_client_sdk_input_error *error) {
    if (out == NULL || *out != NULL)
        return native_failure(error, MC_CLIENT_SDK_INPUT_INVALID_ARGUMENT,
                              "Controllers native environment output", 7);
    mc_client_sdk_controller_environment *env = calloc(1, sizeof(*env));
    if (env == NULL)
        return native_failure(error, MC_CLIENT_SDK_INPUT_ALLOCATION_FAILED,
                              "Controllers concrete cold native environment", 7);
    env->phase = MC_CLIENT_SDK_CONTROLLER_ENV_ALLOCATED;
    *out = env;
    if (error != NULL)
        *error = (mc_client_sdk_input_error){0};
    return MC_CLIENT_SDK_INPUT_OK;
}

mc_client_sdk_input_status
mc_client_sdk_controller_environment_discover(mc_client_sdk_controller_environment *env,
                                              mc_client_sdk_input_error *error) {
    if (error != NULL)
        *error = (mc_client_sdk_input_error){0};
    if (env == NULL)
        return native_failure(error, MC_CLIENT_SDK_INPUT_INVALID_ARGUMENT,
                              "Controllers native environment receiver", 12);
    if (env->active)
        return native_failure(error, MC_CLIENT_SDK_INPUT_BUSY,
                              "Controllers native environment active", 12);
    if (env->phase == MC_CLIENT_SDK_CONTROLLER_ENV_FAILED ||
        env->phase == MC_CLIENT_SDK_CONTROLLER_ENV_RETIRING)
        return native_failure(error, MC_CLIENT_SDK_INPUT_INVALID_PHASE,
                              "Controllers native environment terminal prefix", 12);
    if (env->enumeration_returned)
        return MC_CLIENT_SDK_INPUT_OK;
    env->active = true;
    mc_client_sdk_input_error cause = {0};
    mc_client_sdk_input_status status = MC_CLIENT_SDK_INPUT_OK;
    const uint32_t real_backends =
        mc_client_sdk_controller_native_backends() & ~(uint32_t)MC_CLIENT_SDK_CONTROLLER_VIRTUAL;
    if (real_backends == 0) {
        status = native_failure(&cause, MC_CLIENT_SDK_INPUT_UNSUPPORTED_PROFILE,
                                "Controllers require a configured real SDL joystick backend", 12);
        goto failed;
    }
    if (!env->reference_owned) {
        env->phase = MC_CLIENT_SDK_CONTROLLER_ENV_INITIALIZING;
        env->initialization_attempted = true;
        ++env->init_calls;
        if (!SDL_InitSubSystem(SDL_INIT_JOYSTICK)) {
            status = native_failure(&cause, MC_CLIENT_SDK_INPUT_PLATFORM_FAILED,
                                    "Controllers actual SDL joystick subsystem initialization", 12);
            (void)snprintf(cause.detail, sizeof(cause.detail), "%s", SDL_GetError());
            goto failed;
        }
        env->reference_owned = true;
        env->phase = MC_CLIENT_SDK_CONTROLLER_ENV_SUBSYSTEM;
    }
    ++env->enumeration_calls;
    int count = -1;
    SDL_JoystickID *ids = SDL_GetJoysticks(&count);
    /* Own every returned allocation immediately, including a malformed native
     * extent. NULL/count0 is an error, not the successful empty environment. */
    env->ids = ids;
    env->count = count;
    if (ids == NULL) {
        status = native_failure(&cause, MC_CLIENT_SDK_INPUT_PLATFORM_FAILED,
                                "Controllers actual SDL joystick enumeration", 12);
        (void)snprintf(cause.detail, sizeof(cause.detail), "%s", SDL_GetError());
        goto failed;
    }
    if (count < 0 || (size_t)count > SIZE_MAX / sizeof(*ids) - 1u || ids[count] != 0) {
        status = native_failure(&cause, MC_CLIENT_SDK_INPUT_PLATFORM_FAILED,
                                "Controllers native joystick array extent", 12);
        goto failed;
    }
    for (int index = 0; index < count; ++index)
        if (ids[index] == 0) {
            status = native_failure(&cause, MC_CLIENT_SDK_INPUT_PLATFORM_FAILED,
                                    "Controllers native joystick ID extent", 12);
            goto failed;
        }
    env->enumeration_returned = true;
    env->phase = MC_CLIENT_SDK_CONTROLLER_ENV_ENUMERATED;
    env->active = false;
    return MC_CLIENT_SDK_INPUT_OK;
failed:
    remember(env, &cause);
    env->phase = MC_CLIENT_SDK_CONTROLLER_ENV_FAILED;
    env->active = false;
    if (error != NULL)
        *error = cause;
    return status;
}

static mc_client_sdk_input_status retain_pending(mc_client_event_port *port, const char *operation,
                                                 mc_client_sdk_input_error *error) {
    mc_client_events_error cause = {0};
    const mc_client_events_status status = mc_client_events_retain_pending(port, &cause);
    if (status == MC_CLIENT_EVENTS_OK)
        return MC_CLIENT_SDK_INPUT_OK;
    const mc_client_sdk_input_status mapped =
        status == MC_CLIENT_EVENTS_BUSY                ? MC_CLIENT_SDK_INPUT_BUSY
        : status == MC_CLIENT_EVENTS_ALLOCATION_FAILED ? MC_CLIENT_SDK_INPUT_ALLOCATION_FAILED
        : status == MC_CLIENT_EVENTS_LIMIT             ? MC_CLIENT_SDK_INPUT_LIMIT
                                                       : MC_CLIENT_SDK_INPUT_PLATFORM_FAILED;
    native_failure(error, mapped, operation, -1);
    if (error != NULL) {
        error->site = (mc_client_sdk_input_site){NULL, NULL, NULL, -1};
        error->events = cause;
    }
    return mapped;
}

static mc_client_sdk_input_status retirement_failure(mc_client_sdk_input_error *error,
                                                     mc_client_sdk_input_status status,
                                                     const char *operation) {
    native_failure(error, status, operation, -1);
    if (error != NULL)
        error->site = (mc_client_sdk_input_site){NULL, NULL, NULL, -1};
    return status;
}

mc_client_sdk_input_status
mc_client_sdk_controller_environment_retire(mc_client_sdk_controller_environment **slot,
                                            mc_client_event_port *port,
                                            mc_client_sdk_input_error *error) {
    if (error != NULL)
        *error = (mc_client_sdk_input_error){0};
    if (slot == NULL)
        return retirement_failure(error, MC_CLIENT_SDK_INPUT_INVALID_ARGUMENT,
                                  "Controllers native environment retirement slot");
    mc_client_sdk_controller_environment *env = *slot;
    if (env == NULL)
        return MC_CLIENT_SDK_INPUT_OK;
    if (env->active)
        return retirement_failure(error, MC_CLIENT_SDK_INPUT_BUSY,
                                  "Controllers native environment retirement active");
    const bool effects = env->initialization_attempted || env->ids != NULL || env->reference_owned;
    if (effects && port == NULL)
        return retirement_failure(error, MC_CLIENT_SDK_INPUT_INVALID_ARGUMENT,
                                  "Controllers native cleanup requires the live sole event owner");
    env->phase = MC_CLIENT_SDK_CONTROLLER_ENV_RETIRING;
    env->active = true;
    mc_client_sdk_input_status status = MC_CLIENT_SDK_INPUT_OK;
    if (effects && !env->before_drop_retained) {
        status =
            retain_pending(port, "Controllers retain actual SDL records before native drop", error);
        if (status != MC_CLIENT_SDK_INPUT_OK)
            goto stopped;
        env->before_drop_retained = true;
    }
    if (env->reference_owned) {
        /* Consume our right BEFORE the void external call. A later retention
         * failure retries without issuing a second subsystem drop. */
        env->reference_owned = false;
        ++env->quit_calls;
        SDL_QuitSubSystem(SDL_INIT_JOYSTICK);
    }
    if (effects && !env->after_drop_retained) {
        status =
            retain_pending(port, "Controllers retain actual SDL records after native drop", error);
        if (status != MC_CLIENT_SDK_INPUT_OK)
            goto stopped;
        env->after_drop_retained = true;
    }
    SDL_free(env->ids);
    env->ids = NULL;
    free(env);
    *slot = NULL;
    return MC_CLIENT_SDK_INPUT_OK;
stopped:
    env->active = false;
    return status;
}
